def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find regularly spaced grid lines: rows/columns dominated by a color
    # different from the dominant interior color.
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    def candidates_rows():
        return [r for r, row in enumerate(grid)
                if sum(x != bg for x in row) >= 2]

    def candidates_cols():
        return [c for c in range(w)
                if sum(grid[r][c] != bg for r in range(h)) >= 2]

    # The encoded picture consists of the non-background values at the
    # regularly-spaced crossings, with the separator color represented as 8.
    rs, cs = candidates_rows(), candidates_cols()

    def regular(seq):
        if len(seq) < 2:
            return []
        d = Counter(seq[i+1] - seq[i] for i in range(len(seq)-1)).most_common(1)[0][0]
        return list(range(seq[0], seq[-1] + 1, d))

    rs, cs = regular(rs), regular(cs)
    if not rs or not cs:
        return [[8]]

    out = []
    for r in rs:
        row = []
        for c in cs:
            v = grid[r][c]
            row.append(8 if v == bg else v)
        out.append(row)
    return out
